import numpy as np
import torch


class Solver:
    _torch_t1 = None
    _torch_t2 = None

    def solve(self, problem, **kwargs) -> np.ndarray:
        vec1, vec2 = problem
        n = len(vec1)

        if n <= 500:
            return vec1[:, None] * vec2

        t1 = torch.from_numpy(vec1)
        t2 = torch.from_numpy(vec2)
        return torch.outer(t1, t2).numpy()

